<?php
declare(strict_types=1);namespace App\Entity;use App\Repository\LocationRepository;use Doctrine\Common\Collections\{ArrayCollection,Collection};use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity(repositoryClass:LocationRepository::class)]#[ORM\Table(name:'locations')]
class Location
{
 #[ORM\Id,ORM\GeneratedValue,ORM\Column]private ?int $id=null;#[ORM\Column(length:160)]private string $name='';#[ORM\Column(length:160)]private string $street='';#[ORM\Column(length:20)]private string $postalCode='';#[ORM\Column(length:100)]private string $city='';#[ORM\Column(type:'text',nullable:true)]private ?string $notes=null;#[ORM\Column]private bool $active=true;/** @var Collection<int,LocationAddressVersion> */#[ORM\OneToMany(mappedBy:'location',targetEntity:LocationAddressVersion::class,cascade:['persist'],orphanRemoval:true),ORM\OrderBy(['validFrom'=>'DESC'])]private Collection $addressVersions;
 public function __construct(){$this->addressVersions=new ArrayCollection();}public function getId():?int{return $this->id;}public function getName():string{return $this->name;}public function setName(string $v):self{$this->name=trim($v);return $this;}public function getStreet():string{return $this->getCurrentAddressVersion()?->getStreet()??$this->street;}public function setStreet(string $v):self{$this->street=trim($v);return $this;}public function getPostalCode():string{return $this->getCurrentAddressVersion()?->getPostalCode()??$this->postalCode;}public function setPostalCode(string $v):self{$this->postalCode=trim($v);return $this;}public function getCity():string{return $this->getCurrentAddressVersion()?->getCity()??$this->city;}public function setCity(string $v):self{$this->city=trim($v);return $this;}public function getNotes():?string{return $this->getCurrentAddressVersion()?->getNotes()??$this->notes;}public function setNotes(?string $v):self{$this->notes=$v;return $this;}public function isActive():bool{return $this->active;}public function setActive(bool $v):self{$this->active=$v;return $this;}/** @return Collection<int,LocationAddressVersion> */public function getAddressVersions():Collection{return $this->addressVersions;}public function addAddressVersion(LocationAddressVersion $v):self{if(!$this->addressVersions->contains($v)){$this->addressVersions->add($v);$v->setLocation($this);}return $this;}public function getCurrentAddressVersion(?\DateTimeImmutable $at=null):?LocationAddressVersion{$at??=new \DateTimeImmutable('today',new \DateTimeZone('Europe/Berlin'));foreach($this->addressVersions as $v){if($v->isValidAt($at))return $v;}return null;}public function getAddress():string{$v=$this->getCurrentAddressVersion();return $v?$v->getAddress():trim($this->street.', '.$this->postalCode.' '.$this->city,', ');}
